"""`make docs`: generate docs/cypher.md from the query files' headers."""

from __future__ import annotations

from clew.graph.queries import all_queries


def render() -> str:
    qs = all_queries()
    out = [
        "# Cypher catalog (generated)",
        "",
        "Generated by `make docs` from `clew/graph/queries/*.cypher`. Do not edit by hand.",
        "",
        "| ID | Name | Purpose | Callers |",
        "|---|---|---|---|",
    ]
    for q in qs.values():
        out.append(f"| [{q.id}](#{q.id.lower()}) | `{q.name}` | {q.purpose} | {q.callers} |")
    for q in qs.values():
        out += [
            "",
            f"## {q.id}",
            "",
            f"**{q.name}**: {q.purpose}",
            "",
            f"Params: {q.params}",
            "",
            f"Callers: {q.callers}",
            "",
            "```cypher",
            q.text,
            "```",
        ]
    return "\n".join(out) + "\n"


if __name__ == "__main__":
    print(render(), end="")
